fn main() {
    let mut decoder = FrameDecoder::new();

    // Construct valid frame for payload "HELLO"
    let payload = b"HELLO";
    let len = (payload.len() as u16).to_be_bytes();

    // Test with standard byte sum
    let sum: u32 = payload.iter().map(|&b| b as u32).sum();
    let mut frame_bytes = vec![0xAA, 0x55, len[0], len[1]];
    frame_bytes.extend_from_slice(payload);
    frame_bytes.extend_from_slice(&sum.to_be_bytes());

    // Test chunk splitting (split in half)
    let chunk1 = &frame_bytes[..4];
    let chunk2 = &frame_bytes[4..];

    let res1 = decoder.decode(chunk1).unwrap_or_else(|_| vec![]);
    assert_eq!(res1.len(), 0, "Expected 0 frames for partial chunk");

    let res2 = decoder.decode(chunk2).expect("Failed chunk2 with standard checksum");
    assert_eq!(res2.len(), 1, "Expected 1 frame decoded");
    assert_eq!(res2[0].payload, payload);
    println!("Rust FrameDecoder Test Passed!");
}
